import os
import boto3
from botocore.exceptions import ClientError


def read_secret(secret_id, version_id=None, version_stage="AWSCURRENT"):
    """
    Retrieves a specific version or staged value of a secret from AWS Secrets Manager.
    """
    client = boto3.client(
        "secretsmanager",
        region_name=os.environ.get("AWS_DEFAULT_REGION", "us-east-1")
    )

    params = {"SecretId": secret_id}
    if version_id:
        params["VersionId"] = version_id
    elif version_stage:
        params["VersionStage"] = version_stage

    try:
        response = client.get_secret_value(**params)
        return response.get("SecretString", response.get("SecretBinary"))
    except ClientError as e:
        raise RuntimeError(f"Failed to retrieve secret '{secret_id}': {e}")
